// aimux — public entry for the Node.js binding.
//
// This file is a thin re-export of the typed wrapper in `./src/index.ts`,
// which is the single source of truth for the typed layer. It hides the
// JSON-string boundary of the raw napi API (`./index.js` / `./index.d.ts`,
// auto-generated by napi-rs and left untouched) behind typed inputs/outputs.
//
// Keeping the re-export here preserves the stable `import … from '../index.ts'`
// path used by examples, while `src/index.ts` imports the canonical ts-rs types
// directly from `../../aimux-core/bindings/`.

export * from './src/index.ts'
